const fs = require('fs');
let raw = '';
try { raw = fs.readFileSync(0, 'utf8'); } catch (e) { raw = fs.readFileSync('/dev/stdin', 'utf8'); }
const data = raw.trim().split(/\s+/).map(Number);
const N = data[0], K = data[1], T = data[2];

const P = new Int32Array(N + 1);
for (let j = 1; j <= N; j++) P[j] = data[2 + j];

const p = [];
for (let j = 1; j <= N; j++) if (data[2 + N + j] === 1) p.push(j);

// Reduced problem: choose strictly increasing q_1<...<q_K maximizing sum P[q_i]
// subject to sum |p_i - q_i| <= T (min adjacent swaps to reach a member-set Q).
const Vmax = 9 * K;
const W = Vmax + 1;
const INF = 2000000000;

// F: raw values of current layer; M: prefix-min over rows (positions) of current layer.
const F = new Int32Array((N + 1) * W).fill(INF);
const M = new Int32Array((N + 1) * W).fill(INF);
for (let j = 0; j <= N; j++) M[j * W] = 0; // layer 0: cost 0 for value 0

for (let i = 1; i <= K; i++) {
  const pi = p[i - 1];
  const Wprev = 9 * (i - 1);
  const Wi = 9 * i;
  const hi = N - K + i;

  for (let j = i; j <= hi; j++) {
    const d = pi > j ? pi - j : j - pi;
    const Pj = P[j];
    const rf = j * W;
    if (Pj > 0) F.fill(INF, rf, rf + Pj);
    const mo = rf - W;
    let fo = rf + Pj;
    for (let u = 0; u <= Wprev; u++) F[fo++] = d + M[mo + u];
    const s2 = rf + Wprev + Pj + 1;
    const e2 = rf + Wi + 1;
    if (s2 < e2) F.fill(INF, s2, e2);
  }

  // row i-1 becomes invalid for layer i: clean it in M
  const rc = (i - 1) * W;
  M.fill(INF, rc, rc + Wprev + 1);

  // in-place prefix-min over rows i..hi (reads row j-1 already updated)
  for (let j = i; j <= hi; j++) {
    const rf = j * W;
    const rm = rf - W;
    for (let v = 0; v <= Wi; v++) {
      const a = F[rf + v];
      const b = M[rm + v];
      M[rf + v] = b < a ? b : a;
    }
  }
}

const base = N * W;
let ans = 0;
for (let v = Vmax; v >= 0; v--) {
  if (M[base + v] <= T) { ans = v; break; }
}
console.log(ans);
